import { describe, expect, it } from "vitest";
import { numberToWords } from "@/lib/utils/number-to-words";
import { amountInWordsLocalized, type AmountWordsLang } from "@/lib/utils/number-to-words-i18n";

const ENGLISH_AMOUNTS = [
  0, 0.5, 1, 5, 10, 13, 21, 80, 100, 101, 999, 1000, 1001, 2500.5, 5.25, 41000, 100000,
  1234567.89, 3000000, 999999999999999, -5, -5.25,
];

// Expected strings below were written by hand from the word tables, not generated by the code.
// Currency is the ISO code "USD", appended after the words, as the English call sites do.
const HAND_VERIFIED: Record<Exclude<AmountWordsLang, "en">, Array<[number, string]>> = {
  ur: [
    [0, "صفر صرف USD"],
    [1, "ایک صرف USD"],
    [21, "اکیس صرف USD"],
    [100, "ایک سو صرف USD"],
    [1000, "ایک ہزار صرف USD"],
    [41000, "اکتالیس ہزار صرف USD"],
    [1234567.89, "ایک ملین دو سو چونتیس ہزار پانچ سو سڑسٹھ اور نواسی سینٹ صرف USD"],
    [0.5, "پچاس سینٹ صرف USD"],
  ],
  ar: [
    [0, "صفر فقط USD"],
    [1, "واحد فقط USD"],
    [21, "واحد وعشرون فقط USD"],
    [100, "مائة فقط USD"],
    [1000, "ألف فقط USD"],
    [41000, "واحد وأربعون ألف فقط USD"],
    [1234567.89, "مليون ومائتان وأربعة وثلاثون ألف وخمسمائة وسبعة وستون وتسعة وثمانون سنت فقط USD"],
    [0.5, "خمسون سنت فقط USD"],
  ],
  fa: [
    [0, "صفر فقط USD"],
    [1, "یک فقط USD"],
    [21, "بیست و یک فقط USD"],
    [100, "صد فقط USD"],
    [1000, "یک هزار فقط USD"],
    [41000, "چهل و یک هزار فقط USD"],
    [1234567.89, "یک میلیون و دویست و سی و چهار هزار و پانصد و شصت و هفت و هشتاد و نه سنت فقط USD"],
    [0.5, "پنجاه سنت فقط USD"],
    [-5.25, "منفی پنج و بیست و پنج سنت فقط USD"],
  ],
  ps: [
    [0, "صفر یوازې USD"],
    [1, "یو یوازې USD"],
    [21, "شل او یو یوازې USD"],
    [100, "سل یوازې USD"],
    [1000, "یو زر یوازې USD"],
    [41000, "څلوېښت او یو زر یوازې USD"],
    [1234567.89, "یو ملیون دوه سل دېرش او څلور زر پنځه سل شپېته او اووه او اتیا او نهه سنټ یوازې USD"],
    [0.5, "پنځوس سنټ یوازې USD"],
  ],
};

const SAMPLE_AMOUNTS = [0, 1, 21, 100, 1000, 41000, 1234567.89];
const NON_ENGLISH: Array<Exclude<AmountWordsLang, "en">> = ["ur", "ar", "fa", "ps"];

describe("English output is unchanged", () => {
  it("equals numberToWords() followed by the currency code for every sample amount", () => {
    for (const amount of ENGLISH_AMOUNTS) {
      expect(amountInWordsLocalized(amount, "USD", "en")).toBe(`${numberToWords(amount)} USD`);
    }
  });

  it("matches the known English wording for the sample amounts", () => {
    expect(amountInWordsLocalized(0, "USD", "en")).toBe("Zero USD");
    expect(amountInWordsLocalized(41000, "USD", "en")).toBe("Forty One Thousand Only USD");
    expect(amountInWordsLocalized(1234567.89, "USD", "en")).toBe(
      "One Million Two Hundred Thirty Four Thousand Five Hundred Sixty Seven and Eighty Nine Cents Only USD",
    );
  });
});

describe("hand-verified non-English wording", () => {
  for (const lang of NON_ENGLISH) {
    describe(lang, () => {
      for (const [amount, expected] of HAND_VERIFIED[lang]) {
        it(`${amount} -> ${expected}`, () => {
          expect(amountInWordsLocalized(amount, "USD", lang)).toBe(expected);
        });
      }
    });
  }
});

describe("non-English output is real words, not English or placeholders", () => {
  for (const lang of NON_ENGLISH) {
    it(`${lang}: non-empty Arabic-script words with no ASCII letters before the currency code`, () => {
      for (const amount of SAMPLE_AMOUNTS) {
        const out = amountInWordsLocalized(amount, "USD", lang);
        expect(out.endsWith(" USD")).toBe(true);
        const words = out.slice(0, -" USD".length);
        expect(words.length).toBeGreaterThan(0);
        expect(words).toMatch(/[؀-ۿ]/);
        expect(words).not.toMatch(/[A-Za-z]/);
      }
    });
  }
});

describe("no undefined, NaN or malformed spacing", () => {
  const sweep: number[] = [
    ...Array.from({ length: 2001 }, (_, i) => i),
    0.01, 0.1, 0.99, 1.5, 999.99, 1000.01,
    1e6, 1e9, 1e12, 1e15, 999999999999999, 1e17 + 1000,
    123456789012345.67, -1234567.89, -0.5,
  ];
  for (const lang of NON_ENGLISH) {
    it(`${lang}: every sampled amount renders cleanly`, () => {
      for (const amount of sweep) {
        const out = amountInWordsLocalized(amount, "USD", lang);
        expect(out).not.toMatch(/undefined|NaN|null|Infinity/);
        expect(out).not.toMatch(/\s{2,}/);
        expect(out).toBe(out.trim());
        expect(out.length).toBeGreaterThan(4);
      }
    });
  }
});

describe("edge handling", () => {
  it("throws RangeError for non-finite amounts in non-English languages", () => {
    for (const lang of NON_ENGLISH) {
      expect(() => amountInWordsLocalized(Number.NaN, "USD", lang)).toThrow(RangeError);
      expect(() => amountInWordsLocalized(Number.POSITIVE_INFINITY, "USD", lang)).toThrow(RangeError);
    }
  });

  it("falls back to English for an unknown language value", () => {
    expect(amountInWordsLocalized(41000, "USD", "xx" as AmountWordsLang)).toBe("Forty One Thousand Only USD");
  });

  it("does not print a negative sign for an amount that rounds to zero", () => {
    expect(amountInWordsLocalized(-0.001, "USD", "fa")).toBe("صفر فقط USD");
  });
});
